import{_ as a,o as r,c as o,a3 as t}from"./chunks/framework.BlfGB29P.js";const n="/images/logic-studio/user-guide/function-plan-walkthrough-fr.jpg",m=JSON.parse('{"title":"Plan fonctionnel","description":"","frontmatter":{},"headers":[],"relativePath":"fr/projects/logic-studio/user-guide/function-plan.md","filePath":"fr/projects/logic-studio/user-guide/function-plan.md","lastUpdated":1795291346000}'),i={name:"fr/projects/logic-studio/user-guide/function-plan.md"};function s(l,e,c,d,u,p){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="plan-fonctionnel" tabindex="-1">Plan fonctionnel <a class="header-anchor" href="#plan-fonctionnel" aria-label="Permalink to &quot;Plan fonctionnel&quot;">​</a></h1><h2 id="inverser-un-signal-dans-le-plan-fonctionnel" tabindex="-1">Inverser un signal dans le plan fonctionnel <a class="header-anchor" href="#inverser-un-signal-dans-le-plan-fonctionnel" aria-label="Permalink to &quot;Inverser un signal dans le plan fonctionnel&quot;">​</a></h2><h3 id="_1-ouvrir-le-plan-et-ajouter-les-blocs" tabindex="-1">1. Ouvrir le plan et ajouter les blocs <a class="header-anchor" href="#_1-ouvrir-le-plan-et-ajouter-les-blocs" aria-label="Permalink to &quot;1. Ouvrir le plan et ajouter les blocs&quot;">​</a></h3><p>Ouvre le plan fonctionnel dans l’arborescence. Cherche successivement <code>STATE_IN</code>, <code>NOT</code> et <code>STATE_OUT</code> dans la palette et clique sur chacun pour l’ajouter. Déplace les blocs par leur en-tête pour les placer de gauche à droite dans cet ordre.</p><h3 id="_2-configurer-l-entree" tabindex="-1">2. Configurer l’entrée <a class="header-anchor" href="#_2-configurer-l-entree" aria-label="Permalink to &quot;2. Configurer l’entrée&quot;">​</a></h3><p>Ouvre les propriétés de <code>STATE_IN</code> avec l’icône en forme de roue dentée. Saisis l’identifiant de ton capteur ou de ton entrée de test. La démo utilise <code>binary_sensor.bewegung</code>. Sélectionne le type <code>BOOL</code> et la valeur de démonstration <code>TRUE</code>.</p><h3 id="_3-configurer-la-sortie" tabindex="-1">3. Configurer la sortie <a class="header-anchor" href="#_3-configurer-la-sortie" aria-label="Permalink to &quot;3. Configurer la sortie&quot;">​</a></h3><p>Dans les propriétés de <code>STATE_OUT</code>, saisis un identifiant de cible adapté. La démo utilise <code>light.flur</code>. Laisse le mode de sortie sur <code>BOOL</code>. Un signal booléen vaut <code>TRUE</code> ou <code>FALSE</code>.</p><h3 id="_4-relier-les-broches" tabindex="-1">4. Relier les broches <a class="header-anchor" href="#_4-relier-les-broches" aria-label="Permalink to &quot;4. Relier les broches&quot;">​</a></h3><p>Glisse de la broche ronde <strong>Q</strong> de <code>STATE_IN</code> vers <strong>IN</strong> sur <code>NOT</code>. Relie ensuite <strong>OUT</strong> de <code>NOT</code> à <strong>IN</strong> sur <code>STATE_OUT</code>. Le canevas doit afficher trois blocs et deux connexions.</p><h3 id="_5-lancer-la-simulation" tabindex="-1">5. Lancer la simulation <a class="header-anchor" href="#_5-lancer-la-simulation" aria-label="Permalink to &quot;5. Lancer la simulation&quot;">​</a></h3><p>Clique sur <strong>Simuler</strong>, l’icône en forme de fiole. L’entrée affiche <code>Demo: true</code>. Le bloc <code>NOT</code> inverse cette valeur et <code>STATE_OUT</code> affiche <code>Demo: false</code>. La simulation utilise des valeurs de démonstration et laisse la lampe réelle intacte.</p><h3 id="_6-tester-l-autre-valeur" tabindex="-1">6. Tester l’autre valeur <a class="header-anchor" href="#_6-tester-l-autre-valeur" aria-label="Permalink to &quot;6. Tester l’autre valeur&quot;">​</a></h3><p>Règle la valeur de démonstration sur <code>FALSE</code>, puis simule à nouveau. La sortie doit afficher <code>true</code>. Le bouton de réinitialisation efface l’état de la simulation. Enregistre le projet pour conserver le plan.</p><p><a href="/images/logic-studio/user-guide/function-plan-walkthrough-fr.jpg"><img src="'+n+'" alt="Plan fonctionnel avec STATE_IN, NOT et STATE_OUT. L’entrée simulée est vraie et la sortie est fausse."></a></p><p>Si une liaison est refusée, vérifie les types des broches. S’il manque un identifiant d’entité, vérifie les propriétés de l’entrée et de la sortie. Utilise le bouton de simulation pour cet exercice. <strong>Play</strong> dans la barre du projet lance le moteur d’exécution.</p><h2 id="fonctions" tabindex="-1">Fonctions <a class="header-anchor" href="#fonctions" aria-label="Permalink to &quot;Fonctions&quot;">​</a></h2><h3 id="canevas" tabindex="-1">Canevas <a class="header-anchor" href="#canevas" aria-label="Permalink to &quot;Canevas&quot;">​</a></h3><p>Déplace et relie les blocs. Utilise le zoom ou ajuste la vue à tout le plan.</p><h3 id="parametres" tabindex="-1">Paramètres <a class="header-anchor" href="#parametres" aria-label="Permalink to &quot;Paramètres&quot;">​</a></h3><p>Sélectionne un bloc pour régler la durée d’une minuterie ou la cible d’un compteur.</p><h3 id="liaisons-ha" tabindex="-1">Liaisons HA <a class="header-anchor" href="#liaisons-ha" aria-label="Permalink to &quot;Liaisons HA&quot;">​</a></h3><p>Choisis une entité pour le signal et une action HA autorisée pour la sortie.</p><h3 id="simulation" tabindex="-1">Simulation <a class="header-anchor" href="#simulation" aria-label="Permalink to &quot;Simulation&quot;">​</a></h3><p>Bascule les entrées simulées et observe les valeurs aux broches.</p><h3 id="point-d-arret-et-pas-a-pas" tabindex="-1">Point d’arrêt et pas à pas <a class="header-anchor" href="#point-d-arret-et-pas-a-pas" aria-label="Permalink to &quot;Point d’arrêt et pas à pas&quot;">​</a></h3><p>Mets la simulation en pause et avance d’un cycle pour examiner les valeurs.</p><h3 id="disposition-et-epinglage" tabindex="-1">Disposition et épinglage <a class="header-anchor" href="#disposition-et-epinglage" aria-label="Permalink to &quot;Disposition et épinglage&quot;">​</a></h3><p>Organise le plan tout en conservant la position des blocs épinglés.</p><h3 id="play-et-diagnostic-en-direct" tabindex="-1">Play et diagnostic en direct <a class="header-anchor" href="#play-et-diagnostic-en-direct" aria-label="Permalink to &quot;Play et diagnostic en direct&quot;">​</a></h3><p>Lance le plan enregistré et examine les valeurs et les erreurs.</p><h3 id="compteurs-et-memoires-persistants" tabindex="-1">Compteurs et mémoires persistants <a class="header-anchor" href="#compteurs-et-memoires-persistants" aria-label="Permalink to &quot;Compteurs et mémoires persistants&quot;">​</a></h3><p>Active la sauvegarde pour conserver leurs valeurs après un redémarrage. Une modification du plan peut les réinitialiser.</p><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><p>Si une liaison est refusée, compare les types des broches.</p>',35)])])}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
